const args = process.argv.slice(2);
if (args[0] === "--help" || args[0] === "-h") {
  console.log("Usage: node src/greet.ts [--name <name>]");
  process.exit(0);
}
if (args[0] === "--name") {
  console.log(`Hello, ${args[1] ?? "world"}`);
  process.exit(0);
}
console.log("hello");

