import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";

const hello = spawnSync(process.execPath, ["src/greet.ts"], { encoding: "utf8" });
assert.equal(hello.status, 0);
assert.match(hello.stdout ?? "", /hello/);
const named = spawnSync(process.execPath, ["src/greet.ts", "--name", "Ada"], { encoding: "utf8" });
assert.equal(named.status, 0);
assert.match(named.stdout ?? "", /Hello, Ada/);
console.log("OK: greet");
